/* A shareable test entry. Customer journeys keep the ordinary customer controls. */
(()=>{
'use strict';
const E=L.e,B=L.btn;
L.ambassadorMode=new URLSearchParams(location.search||'').get('ambassador')==='1';
let announcement=0;
L.announceChat=text=>{const el=document.getElementById('chat-announcement');if(!el)return;const token=++announcement;el.textContent='';setTimeout(()=>{if(token===announcement&&L.route==='chat')el.textContent=String(text||'');},60);};
const publicTestRoutes=new Set(['samplePause','ambassadorWelcome','ambassadorGuide','ambassadorSample','ambassadorReset']);
const guard=L.guard;L.guard=()=>{if(publicTestRoutes.has(L.route))return;guard();};
const art=kind=>L.illustration(kind);
L.views.ambassadorWelcome=()=>`<section class="ambassador-entry" data-illustrated-screen="ambassadorWelcome"><div class="topline"><span class="wordmark"><img class="actual-wordmark lumo-wordmark-asset" src="/brand/Lumo-Wordmark-Black.svg" alt="Lumo"></span><span class="pill">Student preview</span></div>${art('clarity')}<h1>Try Lumo.<br>Tell us how it feels.</h1><p class="ambassador-intro">Pay for today. See what comes next.</p><div class="ambassador-boundary"><strong>This is a sample experience.</strong><p>Payments, account details and verification are simulated. Use sample details. Your mobile wallet will not be charged.</p></div><div class="actions">${B('Start from sign-up','L.ambassadorSignup()')}${B('Explore a sample account',"L.go('ambassadorSample')",'secondary')}${L.state.onboarded?B('Continue my Lumo',"L.go(L.state.locked?'signin':'home')",'secondary'):''}${B('See a sample Pause',"L.go('samplePause',{returnTo:'ambassadorWelcome'})",'text-btn')}${B('What to try '+L.icon('arrowRight',17),"L.go('ambassadorGuide')",'text-btn')}</div><p class="small muted">Each phone has its own demo. This version does not send money to another phone.</p></section>`;
L.ambassadorSignup=()=>{if(L.state.onboarded||L.state.setup?.phoneConfirmed||L.state.feedback?.length){L.go('ambassadorReset');return;}L.go('welcome');};
L.views.ambassadorReset=()=>L.header('A fresh start?','This replaces the sample account on this browser.')+art('clarity')+`<p class="small muted">Download any feedback you want to keep first. Your previous sample payments, budget and Money Boxes will be removed.</p><div class="actions">${B('Reset and start sign-up','L.reset()')}${L.state.feedback?.length?B('Download my feedback','L.exportFeedback()','secondary'):''}${B('Keep my current account',"L.go('ambassadorWelcome')",'text-btn')}</div>`;
L.views.ambassadorSample=()=>L.header('A little money to explore.','GH₵720.00 for everyday money. GH₵200.00 in savings.')+art('home')+`<div class="ambassador-boundary"><p>The sample budget has <strong>GH₵320.00</strong> still to cover, leaving <strong>GH₵400.00</strong> after the budget. The <strong>GH₵200.00</strong> laptop Money Box is already in savings and is not deducted again.</p><p>This replaces the demo in this browser. The sample PIN is <strong>123456</strong>. Download any feedback you want to keep first.</p></div><div class="actions">${B('Load sample account','L.explore()')}${L.state.feedback?.length?B('Download my feedback','L.exportFeedback()','secondary'):''}${B('Go back',"L.go('ambassadorWelcome')",'text-btn')}</div>`;
const tasks=[
 ['Start from scratch','Use the sample sign-up details below. Review the sample Ghana Card details, university and email. Create your Lumo account, then choose Add money.'],
 ['Add money','Try a sample MoMo top-up into the operational account. Bank transfer shows the account number and a GIP guide for your existing bank app. Never send real money.'],
 ['Make a small budget','After funding, save food and transport costs. Choose the budget period. Budget costs apply to the operational account; saving a budget does not move money.'],
 ['Create a Money Box','Open Money Boxes separately. Add a box, then fund it from the operational account. Check that the money moves into savings and can be transferred back without counting as spending.'],
 ['Pay for lunch','Open Pay, then Campus Pay → Akua’s Kitchen. If lunch covers a saved Food budget cost, link it beside the amount so it is not counted twice.'],
 ['Try a genuine Pause','With a fresh sample account, review a GH₵450.00 Lumo transfer to Abena as extra spending. The projection leaves GH₵270.00 operational money against GH₵320.00 of budget costs: GH₵50.00 short. Savings remain GH₵200.00. Try editing or cancelling before PIN approval.'],
 ['Follow your money','Open Money Story, choose seven days and a category, then inspect completed spending. Search the list and check the dates and total still agree.'],
 ['Ask your money','Try “I want to spend GH₵70.00 on food tonight”. Change the amount and check the answer against your saved plan.'],
 ['Tell us what happened','Use You → Ambassador guide → Leave feedback. Note what you expected, what happened and where you needed help. Download the feedback file and share it with your Lumo contact.']
];
const taskDestinations=[null,['Add money','addMoney'],['Plan','plan'],['Money Boxes','goals'],['Campus Pay','campusPay'],['Transfers','sendOptions'],['Money Story','moneyStoryHome'],['Chat','chat']];
L.views.ambassadorGuide=()=>L.header('Take Lumo for a spin.','Try it naturally. Honest feedback is useful.')+art('chat')+`<div class="ambassador-boundary"><strong>Use sample details only.</strong><p>Do not enter real Ghana Card details, banking PINs or payment information.</p><details><summary>Sample numbers and account details</summary><p>Sign-up phone: <strong>0241230123</strong><br>Verification code: <strong>123456</strong><br>University: <strong>University of Ghana</strong><br>Email: <strong>kwame@example.com</strong><br>Choose your own demo PIN during sign-up. Sample-account PIN: <strong>123456</strong>.</p><p>MoMo recipient: <strong>0241234567</strong> (sample network detected automatically). Bank recipient: <strong>102345678901</strong> at GCB Bank.</p></details></div><div class="test-list">${tasks.map(([name,description],index)=>`<div class="test-step"><details><summary><strong>${E(name)}</strong></summary><p>${E(description)}</p>${index===0?B('Open sign-up','L.ambassadorSignup()','text-btn'):index===8?B('Leave feedback',"L.go('feedback')",'text-btn'):L.state.onboarded&&!L.state.locked?B('Open '+taskDestinations[index][0],`L.go('${taskDestinations[index][1]}')`,'text-btn'):''}</details></div>`).join('')}</div><p class="small muted">Pause checks the saved budget against operational money. Money Boxes hold separate savings; transfer money back before using it for a payment. Money Box dates are targets, not forecasts. Feedback stays on this browser until you download and share it.</p><div class="actions">${B('Leave feedback',"L.go('feedback')")}${B('Download saved feedback','L.exportFeedback()','secondary')}${B('Load a fresh sample account',"L.go('ambassadorSample')",'secondary')}${B('Back to the start',"L.go('ambassadorWelcome')",'text-btn')}</div>`;
if(L.ambassadorMode){
 const more=L.views.more;L.views.more=()=>more().replace('</section>',`<div class="ambassador-tools">${B('Ambassador guide & feedback',"L.go('ambassadorGuide')",'secondary')}</div></section>`);
 L.route='ambassadorWelcome';L.params={};L.history=[];
}
// Give the input room while typing. The composer remains part of the page layout.
const keepInputReachable=()=>{if(L.updateChatViewport){L.updateChatViewport();return;}if(L.route==='chat'&&document.activeElement?.id==='chatText')document.activeElement.scrollIntoView?.({block:'nearest',behavior:'auto'});};
document.addEventListener('focusin',event=>{if(event.target?.id==='chatText')setTimeout(keepInputReachable,50);});
window.visualViewport?.addEventListener('resize',keepInputReachable);
// The first screen must include every product layer, including scripts below.
if(document.readyState==='loading')document.addEventListener('DOMContentLoaded',()=>L.render(),{once:true});
else L.render();
})();
